// Meta webhook authenticity: X-Hub-Signature-256 is HMAC-SHA256 of the raw
// request body, keyed with the app secret.
function metaBodyIfValid(item) {
  const crypto = require('crypto');
  const headers = item.json.headers || {};
  const secret = $env.META_APP_SECRET || '';
  let raw;
  if (item.binary && item.binary.data && item.binary.data.data) {
    raw = Buffer.from(item.binary.data.data, 'base64').toString('utf8');
  } else {
    raw = JSON.stringify(item.json.body || {});
  }
  const provided = headers['x-hub-signature-256'] || '';
  if (!secret || !provided.startsWith('sha256=')) return null;
  const expected = 'sha256=' + crypto.createHmac('sha256', secret).update(raw, 'utf8').digest('hex');
  const a = Buffer.from(expected);
  const b = Buffer.from(provided);
  if (a.length !== b.length || !crypto.timingSafeEqual(a, b)) return null;
  return JSON.parse(raw);
}
const item = $input.all()[0];
const payload = metaBodyIfValid(item);
if (payload === null) {
  return [{ json: { reject: true, status: 403, message: 'invalid signature' } }];
}

const out = [];
for (const entry of payload.entry || []) {
  for (const messaging of entry.messaging || []) {
    const msg = messaging.message;
    if (!msg || msg.is_echo) continue; // deliveries, reads, echoes
    const psid = (messaging.sender && messaging.sender.id) || '';
    let content = msg.text || null;
    let eventType = 'message';
    if (!content) {
      const kinds = (msg.attachments || []).map((a) => a.type).filter(Boolean).join(', ');
      content = '[' + (kinds || 'attachment') + ' received - media not stored]';
      eventType = 'media_message';
    }
    out.push({
      json: {
        reject: false,
        idempotency_key: 'meta:facebook:' + msg.mid,
        event: {
          channel: 'facebook',
          provider: 'meta',
          external_event_id: msg.mid,
          event_type: eventType,
          external_sender_id: psid || null,
          content,
          received_at: messaging.timestamp
            ? new Date(messaging.timestamp).toISOString()
            : new Date().toISOString(),
          metadata: { page_id: entry.id || null },
        },
      },
    });
  }
}
if (out.length === 0) {
  return [{ json: { reject: true, status: 200, message: 'no messages' } }];
}
return out;

// Meta webhook subscription verification (GET hub.challenge handshake).
const item = $input.all()[0];
const query = item.json.query || {};
const token = $env.META_VERIFY_TOKEN || '';
if (query['hub.mode'] === 'subscribe' && token && query['hub.verify_token'] === token) {
  return [{ json: { reject: false, challenge: query['hub.challenge'] || '' } }];
}
return [{ json: { reject: true, status: 403, message: 'verification failed' } }];
